                        <label key={index} className="option">
                            <input
                                type="checkbox"
                                name={id}
                                value={option}
                                onChange={(e) => onChange(id, option, e.target.checked)}
                            />
                            {option}
                        </label>
                    ))}
                </div>
            </fieldset>
        </div>
    );
};

const Quiz = () => {
    const [answers, setAnswers] = useState({
        q1: [],
        q2: [],
        q3: []
    });
    const [submitted, setSubmitted] = useState(false);

    const questions = [
        {
            id: 'q1',
            question: "1. Which of the following are considered functional programming languages?",
            helpText: "Select all that apply. Functional languages emphasize the use of functions and immutable data.",
            options: ["Haskell", "Lisp", "Elixir", "C"]
        },
        {
            id: 'q2',
            question: "2. Which of these languages were developed or primarily maintained by Microsoft?",
            options: ["C#", "TypeScript", "F#", "Java"]
        },
        {
            id: 'q3',
            question: "3. Which of these languages are commonly used for server-side or client-side web development?",
            options: ["JavaScript", "Python", "PHP", "Assembly"]
        }
    ];

    const handleCheckboxChange = (questionId, option, checked) => {
        setAnswers(prev => {
            const currentAnswers = prev[questionId];
            if (checked) {
                return { ...prev, [questionId]: [...currentAnswers, option] };
            } else {
                return { ...prev, [questionId]: currentAnswers.filter(a => a !== option) };
            }
        });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setSubmitted(true);
        console.log("Submitted answers:", answers);
    };

    return (
        <div className="quiz-container">
            <h1>Computer Languages Quiz</h1>
            <form onSubmit={handleSubmit}>
                {questions.map(q => (
                    <Question
                        key={q.id}
                        id={q.id}
                        question={q.question}
                        helpText={q.helpText}
                        options={q.options}
                        onChange={handleCheckboxChange}
                    />
                ))}
                <button type="submit" className="submit-btn">Submit Quiz</button>
            </form>
            {submitted && (
                <div className="result success" role="alert">
                    Thank you for completing the quiz! Check the console for your responses.
                </div>
            )}
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);

